import { NextRequest, NextResponse } from "next/server";
import { SESSION_COOKIE } from "@/lib/session-cookie";

// Cheap gate: cookie presence only. Real session validation happens
// server-side in the admin layout (Redis lookup needs Node runtime).
export function middleware(req: NextRequest) {
  if (!req.cookies.get(SESSION_COOKIE)) {
    const url = req.nextUrl.clone();
    url.pathname = "/login";
    return NextResponse.redirect(url);
  }
  return NextResponse.next();
}

export const config = { matcher: ["/admin/:path*"] };
import "server-only";
import { randomBytes } from "node:crypto";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { redis } from "./redis";
import { SESSION_COOKIE } from "./session-cookie";

export { SESSION_COOKIE };
const SESSION_TTL_SEC = 7 * 24 * 3600;

export type Session = {
  userId: string;
  businessId: string;
  role: "owner" | "staff";
  name: string;
  email: string;
};

const key = (token: string) => `sess:${token}`;

// Sessions live in Redis: opaque 256-bit token in an httpOnly cookie,
// all session data server-side, TTL-refreshed on each read.
export async function createSession(data: Session): Promise<void> {
  const token = randomBytes(32).toString("hex");
  await redis().set(key(token), JSON.stringify(data), "EX", SESSION_TTL_SEC);
  (await cookies()).set(SESSION_COOKIE, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    maxAge: SESSION_TTL_SEC,
    path: "/",
  });
}

export async function getSession(): Promise<Session | null> {
  const token = (await cookies()).get(SESSION_COOKIE)?.value;
  if (!token) return null;
  const raw = await redis().get(key(token));
  if (!raw) return null;
  await redis().expire(key(token), SESSION_TTL_SEC); // sliding expiration
  return JSON.parse(raw) as Session;
}

export async function requireSession(): Promise<Session> {
  const session = await getSession();
  if (!session) redirect("/login");
  return session;
}

export async function destroySession(): Promise<void> {
  const store = await cookies();
  const token = store.get(SESSION_COOKIE)?.value;
  if (token) await redis().del(key(token));
  store.delete(SESSION_COOKIE);
}
// Importable from edge middleware (no server-only deps).
export const SESSION_COOKIE = "kezek_session";
import Link from "next/link";
import { requireSession } from "@/lib/session";
import { logout } from "@/app/login/actions";

const nav = [
  ["/admin", "Calendar"],
  ["/admin/clients", "Clients"],
  ["/admin/services", "Services"],
  ["/admin/staff", "Staff"],
  ["/admin/reports", "Reports"],
  ["/admin/analytics", "Analytics"],
  ["/admin/notifications", "Notifications"],
  ["/admin/audit", "Audit"],
] as const;

export default async function AdminLayout({ children }: { children: React.ReactNode }) {
  const session = await requireSession();
  return (
    <div className="min-h-screen bg-zinc-50">
      <header className="border-b border-zinc-200 bg-white">
        <div className="mx-auto flex max-w-6xl items-center justify-between gap-4 px-4 py-3">
          <div className="flex items-center gap-6 overflow-x-auto">
            <span className="text-lg font-bold">kezek</span>
            <nav className="flex gap-4 text-sm">
              {nav.map(([href, label]) => (
                <Link key={href} href={href} className="whitespace-nowrap text-zinc-600 hover:text-zinc-900">
                  {label}
                </Link>
              ))}
            </nav>
          </div>
          <form action={logout} className="flex items-center gap-3 text-sm">
            <span className="hidden text-zinc-500 sm:inline">{session.name}</span>
            <button className="rounded-lg border border-zinc-300 px-3 py-1 hover:bg-zinc-100">Sign out</button>
          </form>
        </div>
      </header>
      <main className="mx-auto max-w-6xl p-4">{children}</main>
    </div>
  );
}
"use server";
import bcrypt from "bcryptjs";
import { eq } from "drizzle-orm";
import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { db, schema } from "@/db";
import { rateLimit } from "@/lib/ratelimit";
import { createSession, destroySession } from "@/lib/session";

export async function login(
  _prev: { error: string } | null,
  formData: FormData,
): Promise<{ error: string } | null> {
  const email = String(formData.get("email") ?? "").trim().toLowerCase();
  const password = String(formData.get("password") ?? "");
  if (!email || !password) return { error: "Enter an email and a password" };

  const ip = (await headers()).get("x-forwarded-for")?.split(",")[0] ?? "local";
  if (!(await rateLimit(`login:${ip}`, 10, 60))) {
    return { error: "Too many attempts, wait a minute" };
  }

  const user = await db.query.users.findFirst({ where: eq(schema.users.email, email) });
  if (!user || !(await bcrypt.compare(password, user.passwordHash))) {
    return { error: "Wrong email or password" };
  }
  if (!user.businessId) return { error: "This user is not attached to a business" };

  await createSession({
    userId: user.id,
    businessId: user.businessId,
    role: user.role,
    name: user.name,
    email: user.email,
  });
  redirect("/admin");
}

export async function logout(): Promise<void> {
  await destroySession();
  redirect("/login");
}

