import { and, desc, eq, gte, sql } from "drizzle-orm";
import { db, schema as s } from "@/db";
import { requireSession } from "@/lib/session";
import { RevenueChart } from "./revenue-chart";

export default async function ReportsPage() {
  const session = await requireSession();
  const [biz] = await db.select().from(s.businesses).where(eq(s.businesses.id, session.businessId));
  // Server component renders per request — "now" is legitimately request-scoped.
  // eslint-disable-next-line react-hooks/purity
  const since = new Date(Date.now() - 30 * 24 * 3600_000);

  // Revenue per local day, completed bookings, last 30 days
  const revenue = await db
    .select({
      day: sql<string>`to_char(${s.bookings.startAt} at time zone ${biz.timezone}, 'YYYY-MM-DD')`,
      total: sql<number>`sum(${s.bookings.priceKzt})`,
    })
    .from(s.bookings)
    .where(
      and(
        eq(s.bookings.businessId, session.businessId),
        eq(s.bookings.status, "completed"),
        gte(s.bookings.startAt, since),
      ),
    )
    .groupBy(sql`1`)
    .orderBy(sql`1`);

  const byService = await db
    .select({
      name: s.services.name,
      count: sql<number>`count(*)`,
      total: sql<number>`sum(${s.bookings.priceKzt})`,
    })
    .from(s.bookings)
    .innerJoin(s.services, eq(s.bookings.serviceId, s.services.id))
    .where(
      and(
        eq(s.bookings.businessId, session.businessId),
        eq(s.bookings.status, "completed"),
        gte(s.bookings.startAt, since),
      ),
    )
    .groupBy(s.services.name)
    .orderBy(desc(sql`sum(${s.bookings.priceKzt})`));

  const [counts] = await db
    .select({
      completed: sql<number>`count(*) filter (where status = 'completed')`,
      noShow: sql<number>`count(*) filter (where status = 'no_show')`,
      cancelled: sql<number>`count(*) filter (where status = 'cancelled')`,
      upcoming: sql<number>`count(*) filter (where status = 'confirmed')`,
      revenue: sql<number>`coalesce(sum(price_kzt) filter (where status = 'completed'), 0)`,
    })
    .from(s.bookings)
    .where(and(eq(s.bookings.businessId, session.businessId), gte(s.bookings.startAt, since)));

  const noShowRate =
    Number(counts.completed) + Number(counts.noShow) > 0
      ? Math.round((100 * Number(counts.noShow)) / (Number(counts.completed) + Number(counts.noShow)))
      : 0;

  const tiles = [
    ["Revenue, 30 days", `${Number(counts.revenue).toLocaleString("en-US")} ₸`],
    ["Completed", counts.completed],
    ["Upcoming", counts.upcoming],
    ["No-show", `${counts.noShow} (${noShowRate}%)`],
  ] as const;

  return (
    <div>
      <h1 className="mb-4 text-xl font-semibold">Reports · 30 days</h1>
      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        {tiles.map(([label, value]) => (
          <div key={label} className="rounded-xl border border-zinc-200 bg-white p-4">
            <div className="text-sm text-zinc-500">{label}</div>
            <div className="mt-1 text-2xl font-semibold">{value}</div>
          </div>
        ))}
      </div>

      <section className="mb-6 rounded-xl border border-zinc-200 bg-white p-4">
        <h2 className="mb-3 font-medium text-zinc-700">Revenue by day</h2>
        <RevenueChart data={revenue.map((r) => ({ day: r.day.slice(5), total: Number(r.total) }))} />
      </section>

      <section className="max-w-xl rounded-xl border border-zinc-200 bg-white p-4">
        <h2 className="mb-3 font-medium text-zinc-700">By service</h2>
        <table className="w-full text-sm">
          <tbody>
            {byService.map((r) => (
              <tr key={r.name} className="border-b border-zinc-100 last:border-0">
                <td className="py-2">{r.name}</td>
                <td className="py-2 text-right text-zinc-500">{r.count}×</td>
                <td className="py-2 text-right font-medium">
                  {Number(r.total).toLocaleString("en-US")} ₸
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>
    </div>
  );
}
import { cohorts, revenueTrend, topClients, utilization } from "@/lib/analytics";
import { requireSession } from "@/lib/session";
import { TrendChart } from "./trend-chart";

const kzt = (n: number) => `${n.toLocaleString("en-GB")} ₸`;
const pct = (n: number) => `${Math.round(n * 100)}%`;

export default async function AnalyticsPage() {
  const session = await requireSession();
  const [trend, util, cohortRows, clients] = await Promise.all([
    revenueTrend(session.businessId, 30),
    utilization(session.businessId, 30),
    cohorts(session.businessId, 6),
    topClients(session.businessId, 10),
  ]);

  const widest = Math.max(1, ...cohortRows.map((c) => c.retained.length));

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-xl font-semibold">Analytics</h1>
        <p className="mt-1 text-sm text-zinc-500">
          Postgres window functions: trailing mean, running total, ranks and cohorts.
        </p>
      </div>

      <section className="rounded-xl border border-zinc-200 bg-white p-4">
        <h2 className="mb-1 font-medium text-zinc-700">Revenue, last 30 days</h2>
        <p className="mb-3 text-xs text-zinc-500">
          Bars are daily actuals; the line is a 7-day trailing mean, which smooths the weekly saw-tooth.
        </p>
        <TrendChart data={trend} />
      </section>

      <section>
        <h2 className="mb-2 font-medium text-zinc-700">Staff utilization · 30 days</h2>
        <div className="space-y-2">
          {util.map((u) => (
            <div key={u.staffId} className="rounded-xl border border-zinc-200 bg-white p-3">
              <div className="flex items-baseline justify-between text-sm">
                <span className="font-medium">{u.staffName}</span>
                <span className="text-zinc-500">
                  {Math.round(u.bookedMinutes / 60)} h of {Math.round(u.availableMinutes / 60)} h ·{" "}
                  {kzt(u.revenue)}
                </span>
              </div>
              <div className="mt-2 h-2 w-full overflow-hidden rounded-full bg-zinc-100">
                <div
                  className="h-full rounded-full bg-zinc-900"
                  style={{ width: `${Math.min(100, u.utilization * 100)}%` }}
                />
              </div>
              <div className="mt-1 text-right text-xs text-zinc-500">{pct(u.utilization)}</div>
            </div>
          ))}
          {util.length === 0 && (
            <p className="rounded-xl border border-dashed border-zinc-300 p-6 text-center text-zinc-400">
              No active staff
            </p>
          )}
        </div>
      </section>

      <section>
        <h2 className="mb-2 font-medium text-zinc-700">Cohort retention</h2>
        <p className="mb-2 text-xs text-zinc-500">
          Each row is a month of first visit; each column, how many of them came back N months later.
        </p>
        <div className="overflow-x-auto rounded-xl border border-zinc-200 bg-white">
          <table className="w-full text-sm">
            <thead className="border-b border-zinc-200 text-left text-zinc-500">
              <tr>
                <th className="p-3">Cohort</th>
                <th className="p-3 text-right">Clients</th>
                {Array.from({ length: widest }, (_, i) => (
                  <th key={i} className="p-3 text-right">
                    +{i}
                  </th>
                ))}
