                  <td className="p-3 font-medium">{c.cohort}</td>
                  <td className="p-3 text-right">{c.size}</td>
                  {Array.from({ length: widest }, (_, i) => {
                    const n = c.retained[i] ?? 0;
                    const share = c.size > 0 ? n / c.size : 0;
                    return (
                      <td
